var REGIONS = {"marmara":{"name":{"fr":"Marmara et Istanbul"},"tag":{"fr":"Deux continents, trois empires — et les murs de Troie"}},"aegean":{"name":{"fr":"Côte égéenne"},"tag":{"fr":"Cités de marbre antiques, terrasses thermales et ports blanchis à la chaux"}},"med":{"name":{"fr":"Méditerranée — la Côte turquoise"},"tag":{"fr":"Lagunes bordées de pins, ruines lyciennes et 300 jours de soleil"}},"central":{"name":{"fr":"Anatolie centrale"},"tag":{"fr":"Cheminées de fées, cités souterraines et patrie des derviches tourneurs"}},"north":{"name":{"fr":"Mer Noire"},"tag":{"fr":"Monastères accrochés aux falaises, jardins de thé et villes ottomanes intactes"}},"east":{"name":{"fr":"Anatolie orientale"},"tag":{"fr":"Hauts plateaux, une capitale fantôme et une île-église sur un lac de soude"}},"southeast":{"name":{"fr":"Anatolie du Sud-Est"},"tag":{"fr":"Mésopotamie : le premier temple du monde et des villes plus anciennes que l’histoire"}}};
var D = [{"id":"hagia","img":"https://api.bubixo.com/discover-turkiye/assets/hagia.jpg","region":"marmara","unesco":true,"name":{"fr":"Sainte-Sophie"},"desc":{"fr":"Édifiée en 537 comme la plus grande cathédrale de Byzance, puis mosquée impériale — pendant près de mille ans, ce fut le plus vaste espace couvert du monde. Sa coupole dorée en apesanteur et son histoire en strates en font le bâtiment le plus célèbre de Turquie."},"loc":{"fr":"Sultanahmet, Istanbul"},"best":{"fr":"Avr.–juin et sept.–nov. ; arrivez dès l’ouverture"},"tip":{"fr":"Les visiteurs étrangers parcourent la galerie supérieure (billet ≈ 25 €) ; l’accès touristique est fermé pendant les heures de prière."}},{"id":"blue","img":"https://api.bubixo.com/discover-turkiye/assets/blue.jpg","region":"marmara","unesco":true,"name":{"fr":"Mosquée Bleue et Sultanahmet"},"desc":{"fr":"La mosquée du Sultan Ahmet, couronnée de six minarets et tapissée de 20 000 carreaux d’İznik peints à la main, fait face à Sainte-Sophie de l’autre côté d’une roseraie. Autour s’étend l’ancien quartier impérial : palais de Topkapı, Citerne Basilique et les 4 000 boutiques du Grand Bazar."},"loc":{"fr":"Sultanahmet, Istanbul"},"best":{"fr":"Toute l’année ; le crépuscule pour les plus belles photos"},"tip":{"fr":"L’entrée est gratuite en dehors des cinq prières quotidiennes. Tenue couvrante ; des foulards sont prêtés à la porte."}},{"id":"galata","img":"https://api.bubixo.com/discover-turkiye/assets/galata.jpg","region":"marmara","unesco":false,"name":{"fr":"Galata et le Bosphore"},"desc":{"fr":"Traversez le pont de Galata entre pêcheurs et sandwichs au poisson, montez à la tour génoise du XIVe siècle pour un panorama à 360°, puis prenez un ferry sur le détroit qui sépare l’Europe de l’Asie — la croisière de classe mondiale la moins chère du monde."},"loc":{"fr":"Karaköy / Beyoğlu, Istanbul"},"best":{"fr":"Toute l’année ; le ferry au coucher du soleil est magique"},"tip":{"fr":"Prenez une Istanbulkart pour les ferries, tramways et métros — les ferries de ligne valent mieux que les croisières touristiques hors de prix."}},{"id":"troy","img":"https://api.bubixo.com/discover-turkiye/assets/troy.jpg","region":"marmara","unesco":true,"name":{"fr":"Troie"},"desc":{"fr":"La cité légendaire de l’Iliade d’Homère, où les archéologues ont trouvé neuf villes empilées sur 4 000 ans. Parcourez les murailles antiques, posez devant le cheval de bois, puis approfondissez au remarquable musée de Troie, juste à côté."},"loc":{"fr":"Près de Çanakkale, Dardanelles"},"best":{"fr":"Avr.–juin et sept.–oct."},"tip":{"fr":"À combiner avec les champs de bataille de Gallipoli, de l’autre côté du détroit, pour une journée entière d’histoire."}},{"id":"cappadocia","img":"https://api.bubixo.com/discover-turkiye/assets/cappadocia.jpg","region":"central","unesco":true,"name":{"fr":"Cappadoce"},"desc":{"fr":"Un paysage volcanique surréaliste de cheminées de fées, d’églises rupestres byzantines cachées et de villes souterraines entières. À l’aube, plus de cent montgolfières dérivent au-dessus des vallées de Göreme — l’un des grands spectacles du voyage."},"loc":{"fr":"Göreme / Nevşehir, Anatolie centrale"},"best":{"fr":"Avr.–juin et sept.–nov. pour les vols"},"tip":{"fr":"Réservez la montgolfière à l’avance et prévoyez 2 à 3 matins — les vols sont annulés par vent. Dormez dans un hôtel troglodyte."}},{"id":"pamukkale","img":"https://api.bubixo.com/discover-turkiye/assets/pamukkale.jpg","region":"aegean","unesco":true,"name":{"fr":"Pamukkale et Hiérapolis"},"desc":{"fr":"Le « château de coton » : un versant de terrasses de travertin d’un blanc éblouissant, remplies d’une eau tiède et minérale. Sur le plateau au-dessus s’étendent les ruines de Hiérapolis, où l’on nage entre des colonnes antiques immergées dans la piscine de Cléopâtre."},"loc":{"fr":"Près de Denizli, région égéenne"},"best":{"fr":"Tôt le matin ou à l’heure dorée ; évitez la chaleur de midi"},"tip":{"fr":"On se déchausse sur les terrasses — prévoyez un sac pour vos chaussures et de la prudence : la pierre glisse."}},{"id":"ephesus","img":"https://api.bubixo.com/discover-turkiye/assets/ephesus.jpg","region":"aegean","unesco":true,"name":{"fr":"Éphèse"},"desc":{"fr":"La cité classique la mieux conservée de la Méditerranée orientale. Des rues de marbre passent devant la bibliothèque de Celsus à deux étages, des maisons romaines en terrasses aux fresques intactes et un grand théâtre qui accueillait 25 000 spectateurs."},"loc":{"fr":"Selçuk, près d’İzmir"},"best":{"fr":"Mars–mai et sept.–nov. ; la première heure après l’ouverture"},"tip":{"fr":"Prenez un guide ou un audioguide — les pierres se mettent à parler. Ne manquez pas les Maisons en terrasses (billet séparé)."}},{"id":"oludeniz","img":"https://api.bubixo.com/discover-turkiye/assets/oludeniz.jpg","region":"med","unesco":false,"name":{"fr":"Ölüdeniz et Fethiye"},"desc":{"fr":"Une lagune turquoise parfaitement calme, lovée autour d’une langue de sable blanc, sous des montagnes couvertes de pins — la plage la plus photographiée de Turquie. Les parapentes biplaces s’élancent du Babadağ, à 1 900 m, et descendent en spirale au-dessus de la baie ; la voie lycienne commence tout près."},"loc":{"fr":"Fethiye, Côte turquoise"},"best":{"fr":"Mai–oct. ; juin et septembre sont idéaux"},"tip":{"fr":"Réservez le parapente le matin (air plus calme) et offrez-vous une journée en bateau jusqu’à la vallée des Papillons."}},{"id":"antalya","img":"https://api.bubixo.com/discover-turkiye/assets/antalya.jpg","region":"med","unesco":false,"name":{"fr":"Antalya"},"desc":{"fr":"La capitale de la Riviera turque : une vieille ville ottomane (Kaleiçi) enroulée autour d’un port romain, des cascades qui plongent droit dans la mer et de longues plages adossées aux monts Taurus. Pergé, Aspendos et Side sont à courte distance."},"loc":{"fr":"Côte méditerranéenne"},"best":{"fr":"Avr.–juin et sept.–nov. ; baignade jusqu’en novembre"},"tip":{"fr":"Voyez la cascade du Bas-Düden depuis un bateau, et assistez l’été à un concert au théâtre romain d’Aspendos."}},{"id":"bodrum","img":"https://api.bubixo.com/discover-turkiye/assets/bodrum.jpg","region":"aegean","unesco":false,"name":{"fr":"Bodrum"},"desc":{"fr":"Maisons blanchies à la chaux et bougainvilliers dévalent vers une baie gardée par le château Saint-Pierre, qui abrite un musée d’archéologie sous-marine de rang mondial. C’est ici que se dressait le Mausolée d’Halicarnasse — l’une des Sept Merveilles."},"loc":{"fr":"Péninsule de Bodrum, mer Égée"},"best":{"fr":"Mai–oct. ; le plus animé en plein été"},"tip":{"fr":"Affrétez une gulet traditionnelle pour une « croisière bleue » le long de la côte — même une journée en vaut la peine."}},{"id":"side","img":"https://api.bubixo.com/discover-turkiye/assets/side.jpg","region":"med","unesco":false,"name":{"fr":"Side et Aspendos"},"desc":{"fr":"Une cité portuaire gréco-romaine sur une petite péninsule, où les colonnes de marbre du temple d’Apollon encadrent le coucher de soleil sur la mer. Tout près, Aspendos conserve le théâtre romain le mieux préservé au monde — et l’on y joue encore."},"loc":{"fr":"Manavgat, à l’est d’Antalya"},"best":{"fr":"Avr.–juin et sept.–nov. ; le coucher de soleil au temple"},"tip":{"fr":"Les ruines s’entrelacent avec le village actuel — descendez la rue à colonnades jusqu’à l’ancien port."}},{"id":"konya","img":"https://api.bubixo.com/discover-turkiye/assets/konya.jpg","region":"central","unesco":false,"name":{"fr":"Konya et Mevlâna"},"desc":{"fr":"Le cœur spirituel de la Turquie, où le poète soufi Rûmî enseigna au XIIIe siècle et repose sous une coupole de faïence turquoise. Son mausolée-musée et la fascinante cérémonie du sema des derviches tourneurs attirent des pèlerins de toutes les confessions."},"loc":{"fr":"Konya, Anatolie centrale"},"best":{"fr":"Toute l’année ; festival de Rûmî en décembre"},"tip":{"fr":"Assistez à un vrai sema (le samedi au Centre culturel Mevlâna) et goûtez l’etli ekmek, la galette d’un mètre de Konya."}},{"id":"gobekli","img":"https://api.bubixo.com/discover-turkiye/assets/gobekli.jpg","region":"southeast","unesco":true,"name":{"fr":"Göbekli Tepe"},"desc":{"fr":"Le plus ancien temple monumental connu sur Terre, élevé par des chasseurs-cueilleurs vers 9600 av. J.-C. — quelque 6 000 ans avant Stonehenge. Des cercles de mégalithes en T, gravés de renards, de vautours et de scorpions, réécrivent l’histoire de la civilisation."},"loc":{"fr":"Près de Şanlıurfa, sud-est"},"best":{"fr":"Mars–mai et oct.–nov. ; les étés sont brûlants"},"tip":{"fr":"À combiner avec l’excellent musée archéologique de Şanlıurfa et les bassins aux carpes de Balıklıgöl, dans la vieille ville."}},{"id":"nemrut","img":"https://api.bubixo.com/discover-turkiye/assets/nemrut.jpg","region":"southeast","unesco":true,"name":{"fr":"Mont Nemrut"},"desc":{"fr":"Sur un sommet de 2 134 m, un roi oublié de Commagène fit bâtir son tombeau-sanctuaire, gardé par des têtes de pierre colossales de dieux et d’aigles. Au lever et au coucher du soleil, les statues renversées s’embrasent d’orange au-dessus d’une mer de montagnes — pure irréalité."},"loc":{"fr":"Adıyaman, Taurus oriental"},"best":{"fr":"Mai–oct. (route fermée par la neige en hiver)"},"tip":{"fr":"Montez pour le lever du soleil et prenez de vraies couches chaudes, même en août — le vent du sommet est glacial. Basez-vous à Kâhta ou Karadut."}},{"id":"sumela","img":"https://api.bubixo.com/discover-turkiye/assets/sumela.jpg","region":"north","unesco":false,"name":{"fr":"Monastère de Sumela"},"desc":{"fr":"Un monastère orthodoxe grec fondé au IVe siècle, accroché de façon improbable à une falaise à pic, 300 mètres au-dessus d’une vallée forestière noyée de brume. À l’intérieur, des chapelles restaurées couvertes de fresques éclatantes ; dehors, les paysages les plus verts de la mer Noire."},"loc":{"fr":"Vallée d’Altındere, près de Trabzon"},"best":{"fr":"Mai–oct. ; souvent noyé dans une brume qui ajoute à l’atmosphère"},"tip":{"fr":"À combiner avec le lac de montagne d’Uzungöl et une pause çay — toute la production de thé turc vient de cette région."}},{"id":"ani","img":"https://api.bubixo.com/discover-turkiye/assets/ani.jpg","region":"east","unesco":true,"name":{"fr":"Ani"},"desc":{"fr":"Les ruines saisissantes d’une capitale arménienne médiévale — la « ville aux 1 001 églises » — dispersées sur une steppe herbeuse, à l’extrême bord de la Turquie. Il y a mille ans, elle rivalisait avec Constantinople ; aujourd’hui vous l’aurez sans doute presque pour vous seul."},"loc":{"fr":"À 45 km de Kars, nord-est"},"best":{"fr":"Mai–sept. ; l’hiver est austère mais beau"},"tip":{"fr":"Prévoyez au moins une demi-journée et de bonnes chaussures — le site est vaste. Kars est réputée pour son miel et son fromage gravyer."}},{"id":"van","img":"https://api.bubixo.com/discover-turkiye/assets/van.jpg","region":"east","unesco":false,"name":{"fr":"Lac de Van et Akdamar"},"desc":{"fr":"Le plus grand lac de Turquie — une vaste mer intérieure bleu-soude cernée de volcans. Une courte traversée mène à l’île d’Akdamar et à son église arménienne de la Sainte-Croix, du Xe siècle, sculptée de reliefs bibliques éclatants."},"loc":{"fr":"Van, extrême est"},"best":{"fr":"Mai–sept. ; amandiers en fleur en avril"},"tip":{"fr":"Commencez la journée par le légendaire petit-déjeuner de Van — des dizaines de petites assiettes de fromages, de miel et de kaymak."}},{"id":"mardin","img":"https://api.bubixo.com/discover-turkiye/assets/mardin.jpg","region":"southeast","unesco":false,"name":{"fr":"Mardin"},"desc":{"fr":"Des maisons de pierre couleur de miel dévalent un versant au-dessus de l’infinie plaine mésopotamienne. Minarets, anciens monastères syriaques, ateliers de filigrane d’argent et cafés en cour intérieure en font la ville la plus envoûtante du sud-est turc."},"loc":{"fr":"Anatolie du Sud-Est"},"best":{"fr":"Mars–mai et sept.–nov."},"tip":{"fr":"Visitez le monastère de Deyrulzafaran (du Safran) à l’heure dorée et logez dans une demeure de pierre restaurée."}},{"id":"safranbolu","img":"https://api.bubixo.com/discover-turkiye/assets/safranbolu.jpg","region":"north","unesco":true,"name":{"fr":"Safranbolu"},"desc":{"fr":"Une ville marchande ottomane parfaitement préservée : demeures à colombages, ruelles pavées, un caravansérail du XVIIe siècle et des bazars d’artisans — son nom vient du safran qui pousse toujours dans les champs alentour."},"loc":{"fr":"Karabük, à ~2 h d’Ankara"},"best":{"fr":"Avr.–oct. ; superbe aussi sous la neige"},"tip":{"fr":"Dormez dans un konak (demeure ottomane), goûtez le loukoum au safran et montez à la colline de Hıdırlık pour la vue sur les toits."}},{"id":"uzungol","img":"https://api.bubixo.com/discover-turkiye/assets/uzungol.jpg","region":"north","unesco":false,"name":{"fr":"Uzungöl"},"desc":{"fr":"Un lac de montagne immobile à 1 090 m, avec une mosquée au minaret élancé au bord de l’eau et une forêt d’épicéas qui monte dans la brume — la carte postale de la mer Noire et une échappée fraîche même en plein été."},"loc":{"fr":"Çaykara, Trabzon"},"best":{"fr":"Mai–oct. ; les matins de brume sont magiques"},"tip":{"fr":"Passez la nuit — le lac est le plus calme avant l’arrivée des bus de la journée et après leur départ."}}];
