var TIPS = [{"ico":"M2 12h20M12 2a15 15 0 0 1 0 20 15 15 0 0 1 0-20zM12 2a15 15 0 0 0 0 20","h":{"fr":"Visas et entrée"},"p":{"fr":"De nombreuses nationalités entrent sans visa ou avec un e-Visa rapide via le site officiel evisa.gov.tr. Vérifiez les règles applicables à votre passeport avant de réserver."}},{"ico":"M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6","h":{"fr":"Argent"},"p":{"fr":"La monnaie est la livre turque (₺). Les cartes sont acceptées presque partout, mais gardez des espèces pour les bazars, les taxis et les pourboires — et marchander au bazar est la norme."}},{"ico":"M4 21V8l8-5 8 5v13M9 21v-6h6v6","h":{"fr":"Étiquette dans les mosquées"},"p":{"fr":"Les mosquées se visitent gratuitement en dehors des heures de prière. Épaules et genoux couverts, chaussures à l’entrée, foulard pour les femmes (généralement fourni). Parlez doucement."}},{"ico":"M2.5 19.5L21 12 2.5 4.5l3.5 7.5-3.5 7.5zM6 12h15","h":{"fr":"Se déplacer"},"p":{"fr":"Les distances sont grandes : des vols intérieurs bon marché (THY, Pegasus, AJet) relient toutes les régions, les autocars sont excellents et les trains à grande vitesse desservent Istanbul, Ankara et Konya."}},{"ico":"M3 11l9-8 9 8M5 9v11h14V9M9 20v-7h6v7","h":{"fr":"Museum Pass"},"p":{"fr":"Le Museum Pass Türkiye officiel (muze.gov.tr) couvre des centaines de sites publics — Éphèse, Göbekli Tepe, Topkapı et plus — et évite les files d’attente."}},{"ico":"M18 8a6 6 0 1 1-12 0M12 14v7M8 21h8M5 8h14","h":{"fr":"Cuisine et culture du thé"},"p":{"fr":"Dites oui au çay — le thé est la langue de l’hospitalité. Essayez un petit-déjeuner turc complet, un simit de rue, un pide, des mezze face à la mer et un baklava à la pistache de Gaziantep."}}];
var DETAILS = {"hagia":{"long":{"fr":["On raconte que l’empereur Justinien, entrant dans sa cathédrale achevée en 537, murmura : « Salomon, je t’ai surpassé. » Pendant neuf siècles, Sainte-Sophie fut le cœur battant de la chrétienté byzantine ; après 1453, elle devint la mosquée impériale des Ottomans, qui ajoutèrent minarets, médaillons calligraphiés et loge du sultan tout en préservant soigneusement les mosaïques d’or. Résultat : une Vierge en mosaïque et les noms des califes partagent la même coupole — rien d’autre sur Terre ne ressemble à cela.","À l’intérieur, la coupole de 31 mètres semble flotter sur un anneau de lumière — les contemporains la disaient suspendue au ciel par une chaîne d’or. Cherchez la mosaïque scintillante de la Déisis dans la galerie supérieure, les runes vikings gravées sur un parapet de marbre par un mercenaire qui s’ennuyait il y a mille ans, et la « colonne des vœux » au trou usé par les pouces. Venez tôt, puis regardez au crépuscule les mouettes tourner autour des minarets depuis un café en terrasse."]},"getting":{"fr":"Tram T1 jusqu’à l’arrêt Sultanahmet ; 15 min à pied depuis Sirkeci. Depuis les aéroports, métro M1/M11 ou bus Havaist vers la vieille ville."},"eat":{"fr":"Goûtez les köfte des maisons centenaires de la rue Divanyolu, puis baklava et loukoums dans une confiserie historique près de Sirkeci."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/hagia-1.jpg","cap":{"fr":"L’extérieur du VIe siècle et ses minarets ottomans"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/hagia-2.jpg","cap":{"fr":"La façade vue de la place Sultanahmet"}}]},"blue":{"long":{"fr":["Le sultan Ahmet Ier n’avait que dix-neuf ans lorsqu’il commanda une mosquée destinée à rivaliser avec Sainte-Sophie, de l’autre côté de la place. Achevée en 1616, elle provoqua un scandale à La Mecque : ses six minarets égalaient ceux de la Grande Mosquée, qui dut en ajouter un septième. Le surnom de « Mosquée Bleue » vient de l’intérieur — plus de 20 000 carreaux d’İznik peints à la main, motifs de tulipes, d’œillets et de cyprès, qui luisent sous 260 fenêtres.","La mosquée est le cœur d’un quartier qui fut le centre de deux empires. L’Hippodrome, devant, porte encore un obélisque égyptien de 1500 av. J.-C. ; la Citerne Basilique cache dans la pénombre une forêt de 336 colonnes romaines éclairées depuis l’eau ; le palais de Topkapı déploie cours, harem et trésor sur la pointe de la péninsule ; et le Grand Bazar — 4 000 boutiques sous des voûtes peintes — marchande depuis 1461. Accordez au moins deux journées pleines à Sultanahmet."]},"getting":{"fr":"Tram T1 jusqu’à Sultanahmet ; tout le quartier se parcourt à pied. Entrée gratuite en dehors des cinq prières, tenue couvrante exigée."},"eat":{"fr":"Glissez-vous dans un çay bahçesi (jardin de thé) en cour intérieure entre les deux grandes mosquées : sahlep en hiver, jus de grenade pressé en été."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/blue-1.jpg","cap":{"fr":"Un plafond de bleu d’İznik peint à la main"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/blue-2.jpg","cap":{"fr":"La grande cour à l’heure calme"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/blue-3.jpg","cap":{"fr":"La Citerne Basilique, à cinq minutes à pied"}}]},"galata":{"long":{"fr":["Karaköy et Galata formaient le quartier portuaire des marchands génois, et leur tour de guet de 1348 domine encore la ligne d’horizon au nord de la Corne d’Or. Montez-y (l’ascenseur existe) pour la vue classique à 360° : d’un côté les dômes de la vieille ville, de l’autre le Bosphore qui s’incurve vers la mer Noire. En contrebas, des ruelles pentues pleines de galeries, de torréfacteurs et d’antiquaires dégringolent vers l’eau en passant devant la mosquée Arap, médiévale.","Puis offrez-vous la meilleure chose bon marché d’Istanbul : un ferry de ligne. La traversée vers Kadıköy, ou le tour complet du Bosphore, glisse devant les palais ottomans, les yalıs de bois et la tour de Léandre, avec le çay servi sur le pont pour quelques pièces. Revenez par le pont de Galata au coucher du soleil, quand les pêcheurs bordent les rambardes et que les barques à sandwichs allument leurs grils en dessous."]},"getting":{"fr":"Métro M2 jusqu’à Şişhane, tram T1 jusqu’à Karaköy, ou le funiculaire historique du Tünel — deuxième plus ancien métro du monde, en service depuis 1875."},"eat":{"fr":"Balık ekmek (sandwich au poisson grillé) près du pont, künefe dans les pâtisseries de Karaköy, et café de troisième vague en haut de la côte, à Galata."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/galata-1.jpg","cap":{"fr":"La tour génoise au-dessus des toits de Galata"}}]},"troy":{"long":{"fr":["Pendant des siècles, les érudits ont tenu Troie pour pure poésie — jusqu’à ce que Heinrich Schliemann creuse le tertre d’Hisarlık dans les années 1870 et trouve non pas une ville, mais neuf, empilées comme les pages d’un livre sur 4 000 ans. La couche dite Troie VII, détruite par le feu vers 1180 av. J.-C., est la meilleure candidate pour la guerre d’Homère. On suit encore les murailles en pente qui auraient résisté dix ans aux Grecs, on gravit la rampe où roulaient les chars, on se tient dans le sanctuaire où l’on faisait des offrandes mille ans avant Rome.","Le site récompense l’imagination, et le musée de Troie voisin, primé, la nourrit : quatre étages de bijoux d’or, d’armes et de sarcophages racontent l’histoire mieux qu’aucun guide. Le cheval de bois géant à l’entrée est du pur théâtre — grimpez-y quand même. De l’autre côté des Dardanelles s’étendent les champs de bataille de Gallipoli, en 1915 : une fin d’après-midi émouvante qui referme 3 000 ans de guerres autour de ces mêmes détroits."]},"getting":{"fr":"30 min en voiture ou minibus depuis Çanakkale (vol depuis Istanbul, ou 5-6 h en bus/voiture par le pont de Gallipoli)."},"eat":{"fr":"Le front de mer de Çanakkale sert d’excellentes sardines grillées et le peynir helvası, halva local au fromage — goûtez les deux après les ruines."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/troy-1.jpg","cap":{"fr":"Le cheval de bois sur le front de mer de Çanakkale"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/troy-2.jpg","cap":{"fr":"Neuf villes dans un seul tertre, à Hisarlık"}}]},"ephesus":{"long":{"fr":["Éphèse était le New York de l’Orient romain : une métropole portuaire de 200 000 habitants où le temple d’Artémis — l’une des Sept Merveilles — attirait les pèlerins de toute la Méditerranée. Saint Paul y prêcha (et y déclencha une émeute) dans le grand théâtre ; la Vierge Marie aurait passé ses dernières années dans une petite maison de pierre, sur la colline au-dessus. Ce qui subsiste est stupéfiant : avenues de marbre creusées par les roues des chariots, façade de bibliothèque à deux étages qui abritait 12 000 rouleaux, latrines publiques, lupanar et publicités gravées dans le pavé.","Ne manquez pas les Maisons en terrasses sous leur toit de protection — demeures romaines à sols de mosaïque, murs peints et chauffage par le sol, abandonnées en plein chantier au IIIe siècle, comme si les peintres venaient de partir. Venez à l’ouverture ou en fin d’après-midi : à la mi-journée les groupes des bateaux de croisière submergent le site, et l’été le marbre renvoie une chaleur redoutable."]},"getting":{"fr":"À 3 km de Selçuk — en taxi, en dolmuş ou même à pied. Selçuk est à 1 h de train ou de voiture de l’aéroport d’İzmir."},"eat":{"fr":"Şirince, village de collines aux vieilles maisons grecques à 8 km, est l’endroit d’un long déjeuner : petit-déjeuner de village, gözleme et vins de fruits."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ephesus-1.jpg","cap":{"fr":"Le Grand Théâtre et ses 25 000 places"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ephesus-2.jpg","cap":{"fr":"Le temple d’Hadrien, rue des Curètes"}}]},"pamukkale":{"long":{"fr":["Dix-sept sources chaudes saturées de calcium dévalent ce versant depuis deux millions d’années, y laissant une cascade figée de terrasses d’un blanc éclatant — le « château de coton ». Les Romains, qui ne gâchaient jamais un bain chaud, bâtirent sur le plateau la ville thermale de Hiérapolis ; on venait de tout l’empire prendre les eaux, et beaucoup y restèrent pour toujours : d’où l’une des plus vastes nécropoles antiques d’Anatolie.","Montez pieds nus entre les vasques bleues et peu profondes (chaussures à la main — c’est la règle qui garde le travertin blanc), puis explorez Hiérapolis : un théâtre magnifiquement pentu, le martyrium de saint Philippe et la Piscine antique, où l’on nage dans une eau tiède et pétillante au-dessus de colonnes de marbre renversées. À l’heure dorée, tout le versant vire au rose — les excursionnistes sont partis, et les terrasses n’ont jamais paru aussi irréelles."]},"getting":{"fr":"20 min de Denizli en dolmuş fréquents ; Denizli a un aéroport (DNZ) et des trains rapides depuis İzmir. Beaucoup l’associent à Éphèse."},"eat":{"fr":"Le village de Pamukkale sert un généreux köy kahvaltısı (petit-déjeuner de village) au miel local ; Denizli est réputée pour son agneau tandır longuement cuit."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/pamukkale-1.jpg","cap":{"fr":"Les vasques en terrasses au bord du travertin"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/pamukkale-2.jpg","cap":{"fr":"Le versant blanc vu du fond de la vallée"}}]},"bodrum":{"long":{"fr":["L’antique Halicarnasse a donné au monde deux merveilles : l’historien Hérodote et le Mausolée du roi Mausole, tombeau si grandiose qu’il devint une Merveille du monde — et le mot qui désigne depuis tout tombeau monumental. Ses pierres furent plus tard réemployées par les chevaliers de Saint-Jean dans le château Saint-Pierre, qui veille aujourd’hui sur le port et abrite le musée d’Archéologie sous-marine : épaves de l’âge du bronze, cargaisons de verre et l’or d’une princesse mycénienne, tous remontés du fond de l’Égée.","Le Bodrum d’aujourd’hui est le Saint-Tropez turc : maisons cubiques blanchies sous les bougainvilliers, marina de super-yachts et de gulets en bois, vergers de mandariniers, beach-clubs et vie nocturne fameusement tardive. La péninsule garde des coins plus calmes — les tables de poisson au bord de l’eau à Gümüşlük, les baies de planche à voile de Bitez, les ruines de pierre de Sandima sur sa colline. Le grand classique reste la « croisière bleue » : des jours à naviguer de crique déserte en crique déserte, où la seule décision est l’heure du bain."]},"getting":{"fr":"Vol jusqu’à Milas-Bodrum (BJV), à 40 min de la ville ; des bus desservent toute la côte égéenne. En saison, ferries vers Kos et Rhodes."},"eat":{"fr":"Poisson et mezze au coucher du soleil à Gümüşlük, desserts à la mandarine partout — celles de la péninsule sont réputées — et lokma près de la marina."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/bodrum-1.jpg","cap":{"fr":"Gulets et yachts dans le port de Bodrum"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/bodrum-2.jpg","cap":{"fr":"Une marina tranquille sur la péninsule"}}]},"oludeniz":{"long":{"fr":["Ölüdeniz signifie « mer morte » — non à cause du sel, mais parce que la lagune reste lisse comme un miroir même quand la tempête agite la Méditerranée au-delà du cordon de sable. Protégée en parc naturel, c’est le point le plus photographié de la côte turque : une courbe de sable blanc et de pins autour d’une eau qui passe du jade au saphir profond. Venez tôt — la lumière est la plus belle et le banc de sable le plus vide avant dix heures.","La station au-dessus est aussi l’un des grands centres mondiaux de parapente. Les pilotes biplaces décollent du Babadağ, à 1 900 mètres, et passent une demi-heure à descendre en spirale au-dessus de la lagune ; aucune expérience requise, juste du cran à la course d’élan. Des bateaux partent de la plage vers la vallée des Papillons, communauté nichée dans un canyon accessible seulement par la mer, et la voie lycienne — le sentier de grande randonnée le plus célèbre de Turquie — entame ses 540 km juste à côté, à Ovacık."]},"getting":{"fr":"25 min en dolmuş depuis Fethiye ; l’aéroport le plus proche est Dalaman (DLM), à 1 h avec navettes."},"eat":{"fr":"Au marché aux poissons de Fethiye, vous achetez la prise et les tables alentour la cuisinent ; terminez par une glace sur la promenade."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/oludeniz-1.jpg","cap":{"fr":"La lagune et son célèbre banc de sable"}}]},"antalya":{"long":{"fr":["Fondée vers 150 av. J.-C. par un roi de Pergame, Antalya accueille les arrivants depuis toujours — Hadrien reçut une porte de marbre à trois arches pour sa visite de 130 apr. J.-C., et elle reste la plus belle entrée de Kaleiçi, la vieille ville fortifiée. À l’intérieur, un dédale de demeures ottomanes, de cours parfumées à la mandarine et un minaret cannelé du XIIIe siècle, le tout enroulé autour d’un minuscule port romain taillé dans la falaise.","La ville est aussi la porte des sites antiques de Pamphylie — les rues à colonnades de Pergé, le théâtre d’Aspendos, les temples en bord de mer de Side — et d’un littoral qui va des cascades du Düden, tombant de la falaise, au long ruban de galets de Konyaaltı sous les monts Taurus. La saison de baignade s’étire d’avril à novembre, et en hiver on peut skier à Saklıkent le matin et se baigner (vaillamment) après le déjeuner."]},"getting":{"fr":"L’aéroport d’Antalya (AYT) reçoit des vols directs de toute l’Europe ; tramway jusqu’à la vieille ville en 40 min. Pergé et Aspendos se font en demi-journée."},"eat":{"fr":"Le piyaz (salade de haricots blancs au tahini) est le plat emblématique d’Antalya ; mangez-le avec des köfte dans le quartier du bazar, puis un jus d’orange pressée du cru."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/antalya-1.jpg","cap":{"fr":"Le théâtre romain d’Aspendos, à une courte excursion vers l’est"}}]},"side":{"long":{"fr":["Side fut le grand port de Pamphylie — marché aux esclaves, repaire de pirates et, à l’époque romaine, cité assez riche pour paver sa rue principale de marbre et la border de colonnades. Cléopâtre et Marc Antoine s’y seraient rencontrés. Les ruines n’ont jamais été abandonnées : un village de pêcheurs s’est installé à l’intérieur au XIXe siècle, si bien qu’on passe aujourd’hui devant un théâtre de 15 000 places et une basilique byzantine pour rejoindre des jardins de pension et des bars de plage.","À la pointe même de la péninsule, cinq colonnes relevées du temple d’Apollon encadrent la mer — au coucher du soleil, la vue la plus romantique de toute la Méditerranée turque. À vingt minutes dans les terres, le théâtre d’Aspendos est le mieux conservé du monde romain : son mur de scène tient encore sur toute la hauteur des 41 gradins. Si vous le pouvez, assistez-y à un opéra ou à un ballet par une nuit d’été."]},"getting":{"fr":"À 75 km à l’est de l’aéroport d’Antalya ; bus et dolmuş passent par Manavgat. Aspendos et les chutes de Manavgat sont sur la route."},"eat":{"fr":"Des restaurants de poisson cernent l’ancien port sous le temple ; dans les terres, Manavgat est réputée pour sa truite de rivière grillée et ses brochettes çöp şiş."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/side-1.jpg","cap":{"fr":"Les colonnes d’Apollon à la pointe de la péninsule"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/side-2.jpg","cap":{"fr":"Aspendos — le théâtre le mieux conservé du monde romain"}}]},"cappadocia":{"long":{"fr":["Trois volcans ont enseveli ce plateau sous les cendres il y a des millions d’années ; le vent et la pluie ont ensuite sculpté le tuf tendre en minarets, en champignons et en « cheminées de fées », et les hommes ont fini le travail — creusant maisons, pigeonniers, monastères et des villes souterraines entières, profondes de huit niveaux, où les premiers chrétiens se cachaient avec leur bétail, leurs pressoirs et leurs chapelles. Au musée de plein air de Göreme, des fresques du XIe siècle flamboient encore dans les églises rupestres.","Presque tout le monde s’envole : par matin calme, plus de cent montgolfières s’élèvent à l’aube au-dessus des vallées, l’un des grands spectacles du voyage. Choisissez un opérateur agréé, gardez des matins de réserve en cas de vent, et passez le reste de vos journées à marcher dans la vallée des Roses et les gorges d’Ihlara, à visiter les villes souterraines de Kaymaklı ou Derinkuyu, et à dormir dans un hôtel troglodyte — les chambres y restent naturellement fraîches tout l’été."]},"getting":{"fr":"Vol jusqu’à Nevşehir (NAV) ou Kayseri (ASR), à moins d’1 h de Göreme en navette. Les bus de nuit depuis Istanbul mettent environ 11 h."},"eat":{"fr":"Le testi kebab — viande mijotée dans une jarre d’argile scellée, brisée devant vous — accompagné des vins locaux Emir et Kalecik Karası, nés d’un sol volcanique."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/cappadocia-1.jpg","cap":{"fr":"Décollage à l’aube au-dessus de Göreme"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/cappadocia-2.jpg","cap":{"fr":"Les vallées depuis la nacelle d’une montgolfière"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/cappadocia-3.jpg","cap":{"fr":"Les églises rupestres du parc national de Göreme"}}]},"konya":{"long":{"fr":["« Viens, viens, qui que tu sois » — l’invitation attribuée à Jalâl ad-Dîn Rûmî, mystique et poète soufi du XIIIe siècle, définit encore sa ville. Konya était la capitale des sultans seldjoukides quand la famille de Rûmî y arriva, fuyant les Mongols, et leur plus belle architecture subsiste : le sanctuaire à coupole turquoise où il repose, les médersas İnce Minareli et Karatay avec leurs voûtes de faïence constellées d’étoiles, et la mosquée Alaeddin sur son tertre antique.","Les disciples de Rûmî fondèrent l’ordre mevlevi — les derviches tourneurs — dont la cérémonie du sema transforme le deuil en une lente méditation tournoyante. Voyez-en une authentique le samedi soir au Centre culturel Mevlâna (c’est un office, pas un spectacle : on n’applaudit pas). En décembre revient le Şeb-i Arûs, anniversaire de la « nuit de noces » de Rûmî avec le divin, quand pèlerins et lecteurs de poésie emplissent la ville. La Konya d’aujourd’hui est pieuse, prospère et calme — la Turquie à son plus serein."]},"getting":{"fr":"Les trains à grande vitesse relient Konya en ~2 h d’Ankara et ~4 h 30 d’Istanbul ; l’aéroport (KYA) a des vols quotidiens vers Istanbul."},"eat":{"fr":"L’etli ekmek — un mètre de galette fine à l’agneau épicé — avec le fırın kebabı (mouton rôti au four) et la soupe de gombos, classique des mariages de Konya."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/konya-1.jpg","cap":{"fr":"Le sema — la prière en mouvement"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/konya-2.jpg","cap":{"fr":"Le mausolée de Rûmî et sa coupole de faïence turquoise"}}]},"sumela":{"long":{"fr":["La légende raconte que deux moines athéniens, guidés par une vision de la Vierge, fondèrent Sumela en 386 sur une corniche qu’aucun bâtisseur sensé n’aurait choisie : une paroi à pic, 300 mètres au-dessus de la vallée d’Altındere. Ce qui y poussa en seize siècles — chapelles, cuisines, cellules, une source sacrée et une bibliothèque — s’accroche au rocher comme un nid d’hirondelle, et son église rupestre resplendit de fresques de prophètes, d’apôtres et d’empereurs byzantins, superposées par des générations de peintres.","Le monastère s’est vidé en 1923 lors de l’échange de populations, mais la restauration a rendu vie à ses fresques. La moitié de l’expérience tient au décor : la montée à travers hêtres et pins, les nuages qui dérivent sous les bâtiments, le grondement du torrent tout en bas. C’est la Turquie verte, humide et alpine — associez-la aux terrasses de thé de Rize et au lac de montagne d’Uzungöl pour un circuit complet de la mer Noire."]},"getting":{"fr":"À 45 km de Trabzon (aéroport TZX) ; excursions et dolmuş quotidiens. Une navette assure la dernière montée depuis le parking de la vallée."},"eat":{"fr":"Les classiques de la mer Noire : muhlama (fondue de semoule de maïs et fromage), anchois frais en saison et Laz böreği en dessert — avec du thé de Rize à volonté."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/sumela-1.jpg","cap":{"fr":"Le monastère depuis la route de la vallée"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/sumela-2.jpg","cap":{"fr":"Les parois boisées du parc national d’Altındere"}}]},"safranbolu":{"long":{"fr":["Safranbolu s’est enrichie de deux choses : le safran des champs alentour, toujours parmi les épices les plus précieuses du monde, et sa position sur la route caravanière ottomane d’Istanbul à la mer Noire. Les marchands ont versé leur fortune dans quelque 2 000 konak à colombages — trois étages, encorbellements, plafonds sculptés, bassins intérieurs pour rafraîchir — et comme le XXe siècle a contourné la ville, presque tout a survécu intact, ce qui lui a valu le classement UNESCO en 1994.","Pour l’effet complet, dormez dans un konak restauré : planchers qui craquent, portes basses, petit-déjeuner dans une cour ombragée. Flânez sous l’arcade artisanale des Yemeniciler, prenez un café dans le caravansérail Cinci Han du XVIIe siècle, montez à la colline de Hıdırlık pour le panorama classique de toits rouges, et achetez du loukoum au safran à des familles qui cultivent le crocus depuis des générations. L’hiver, la neige sur les toits en fait un conte."]},"getting":{"fr":"~2 h en voiture ou en bus depuis Ankara, 5 h depuis Istanbul ; les bus arrivent à Kıranköy, à courte distance au-dessus du quartier historique de Çarşı."},"eat":{"fr":"Loukoum et thé au safran, kuyu kebabı (agneau rôti en fosse) et pâtisserie bükme — puis un café turc dans la cour d’un caravansérail."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/safranbolu-1.jpg","cap":{"fr":"Des konak le long d’une ruelle pavée"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/safranbolu-2.jpg","cap":{"fr":"La tour de l’horloge au-dessus de la vieille ville"}}]},"uzungol":{"long":{"fr":["Un glissement de terrain a barré le ruisseau Haldizen il y a des siècles, laissant Uzungöl — le « lac long » — un ruban d’eau verte au fond d’une vallée alpine escarpée, avec un village et une mosquée au minaret élancé sur sa rive, et des épicéas qui montent dans la brume de tous côtés. À 1 090 mètres, l’air reste frais même en août, et le décor évoque davantage les Alpes ou le Caucase que l’idée qu’on se fait de la Turquie.","La boucle plate du bord de lac se marche en moins d’une heure ; ensuite, montez : les pistes de yayla (alpages) grimpent vers Şekersu et au-delà, là où les bergers passent l’été et où les nuages flottent sous vos pieds. Le village fait une base confortable pour toute la région — monastère de Sumela, plateau d’Ayder et pays du thé de Rize sont à portée de journée. Venez en semaine ou hors saison si vous le pouvez : les week-ends d’été sont animés et bruyants."]},"getting":{"fr":"99 km depuis l’aéroport de Trabzon via Of et la vallée de Solaklı — environ 1 h 30 en voiture, minibus ou excursions quotidiennes."},"eat":{"fr":"Truite fraîche des élevages du lac, muhlama bouillonnant dans sa poêle de cuivre, beurre et miel du pays au petit-déjeuner — la cuisine de montagne à son meilleur."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/uzungol-1.jpg","cap":{"fr":"La mosquée au bord du lac, dans sa vallée"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/uzungol-2.jpg","cap":{"fr":"La vue depuis la plateforme d’observation"}}]},"ani":{"long":{"fr":["Vers l’an 1000, Ani comptait peut-être 100 000 habitants et commerçait sur la route de la Soie à égalité avec Constantinople et Le Caire. Capitale du royaume arménien des Bagratides, elle était si constellée de sanctuaires que les chroniqueurs l’appelaient la ville aux 1 001 églises. Vinrent ensuite les conquêtes — byzantine, seldjoukide, mongole — un séisme en 1319, le déplacement des routes commerciales, et enfin le silence. Ce qui subsiste se dresse seul sur un plateau d’herbe cerné par les gorges de l’Akhourian, sur la frontière même avec l’Arménie.","On erre de ruine en ruine avec les alouettes pour compagnie : la cathédrale dont l’architecte répara aussi la coupole de Sainte-Sophie, l’église ronde de Saint-Grégoire peinte du sol au plafond, un palais seldjoukide, une mosquée dominant les gorges, les vestiges d’un pont vieux de 1 600 ans. Peu d’endroits au monde sont aussi chargés de grandeur disparue. Emportez de l’eau, de quoi vous protéger du soleil, et comptez au moins une demi-journée ; associez la visite à l’architecture de pierre de Kars, d’allure balte, et à ses fameux petits-déjeuners au miel et au fromage."]},"getting":{"fr":"À 45 km à l’est de Kars (aéroport KSY, vols d’Istanbul et d’Ankara) ; taxis et petits tours font le trajet, ou conduisez vous-même sur les routes désertes de la steppe."},"eat":{"fr":"Kars est la capitale fromagère de la Turquie : gravyer affiné, miel des prairies de montagne et, l’hiver, oie rôtie à la mode locale."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ani-1.jpg","cap":{"fr":"L’église Saint-Grégoire au-dessus des gorges"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ani-2.jpg","cap":{"fr":"Fresques médiévales dans l’église de Tigran Honents"}}]},"van":{"long":{"fr":["Le lac de Van est une mer intérieure sept fois grande comme le Léman, à l’eau alcaline si riche en minéraux qu’on peut y laver du linge — et y nager tout l’été, porté par la flottaison. Sur ses rives naquit et s’éteignit le royaume d’Urartu, à l’âge du fer ; leur citadelle du IXe siècle av. J.-C., le château de Van, s’étire encore sur une crête rocheuse au-dessus de la ville moderne, avec des inscriptions cunéiformes taillées dans la falaise.","Le joyau du lac est l’île d’Akdamar, où l’église arménienne de la Sainte-Croix, du Xe siècle, porte sa Bible à l’extérieur : Jonas et la baleine, David et Goliath, Adam et Ève, tous sculptés en relief dans une pierre rosée, avec en toile de fond le mont Süphan enneigé. Les bateaux font la traversée de 20 minutes toute la journée. En ville, cherchez les fameux chats de Van, nageurs et duveteux — un œil bleu, un œil ambre — et accordez une matinée entière au petit-déjeuner de Van, institution de quarante petites assiettes."]},"getting":{"fr":"L’aéroport de Van (VAN) a des vols directs d’Istanbul et d’Ankara. Les bateaux pour Akdamar partent de Gevaş, à 45 km au sud-ouest de la ville."},"eat":{"fr":"Le petit-déjeuner de Van : otlu peynir (fromage aux herbes), kaymak au miel, murtuğa et thé à l’infini — plus le poisson du lac, le muge perlé, grillé."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/van-1.jpg","cap":{"fr":"L’île d’Akdamar et l’église de la Sainte-Croix"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/van-2.jpg","cap":{"fr":"Les reliefs bibliques sur les murs de l’église"}}]},"gobekli":{"long":{"fr":["Göbekli Tepe a réécrit l’histoire humaine. Vers 9600 av. J.-C. — avant l’agriculture, la poterie et la roue — des chasseurs-cueilleurs ont hissé sur cette colline des piliers de calcaire de 10 tonnes et dressé des cercles de mégalithes sculptés : renards, grues, scorpions, serpents et léopards à l’affût, avec des bras et des mains repliés sur les pierres en T comme si elles étaient des êtres. Les archéologues ont longtemps supposé que la religion venait après la sédentarisation ; ici, semble-t-il, le temple est venu d’abord, et les villages ont poussé pour le servir.","Une fraction seulement est fouillée — la géophysique révèle au moins quinze autres cercles encore enfouis — vous ne voyez donc que la bordure visible de quelque chose de bien plus vaste. Des passerelles font le tour de l’enceinte principale sous sa couverture ; venez tôt ou tard pour la lumière douce et le calme. Ensuite, à Şanlıurfa, l’excellent musée archéologique conserve les trouvailles (dont la plus ancienne statue humaine grandeur nature), et les bassins sacrés aux carpes de Balıklıgöl s’illuminent au crépuscule. Karahan Tepe, site jumeau à l’allure plus ancienne encore, est à une heure de route."]},"getting":{"fr":"À 22 km de Şanlıurfa (aéroport GNY) ; taxis, excursions et une navette depuis le musée circulent chaque jour. Venez tôt : la chaleur d’été est redoutable."},"eat":{"fr":"Urfa est un pèlerinage gastronomique à elle seule : çiğ köfte préparé à l’ancienne, lahmacun au four à bois, piment isot dans tout, et künefe pour finir."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/gobekli-1.jpg","cap":{"fr":"Les piliers en T de l’enceinte C"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/gobekli-2.jpg","cap":{"fr":"Le bestiaire gravé de la pierre au Vautour"}}]},"nemrut":{"long":{"fr":["Antiochos Ier de Commagène régnait sur un petit royaume tampon entre Rome et la Perse — et décida qu’on se souviendrait de lui comme d’aucun des deux. Sur sa plus haute montagne, il fit élever un tumulus funéraire de 50 mètres en pierraille, flanqué de terrasses où il s’est fait trôner parmi Zeus, Apollon et Héraclès : un dieu autoproclamé, dans une lignée qu’il faisait remonter à la fois à Alexandre et à Darius. Les séismes ont fait tomber les têtes des corps de neuf mètres, et c’est cette image que tout le monde vient chercher : des visages de pierre colossaux contemplant sereinement une mer de montagnes.","Le rituel est l’essentiel : monter dans le noir, gravir les 600 derniers mètres de sentier et regarder le lever du soleil embraser la terrasse est (ou le couchant, la terrasse ouest). Même en août, emportez une vraie veste — le vent du sommet mord. Sa chambre funéraire, au cœur du tumulus, n’a jamais été retrouvée. À la descente, arrêtez-vous au pont romain de Cendere et au tumulus de Karakuş, et pensez Nemrut et Şanlıurfa comme un même itinéraire avec Göbekli Tepe."]},"getting":{"fr":"Basez-vous à Kâhta ou au village de Karadut (aéroport d’Adıyaman à 1 h 30) ; la route est ouverte environ de mai à octobre."},"eat":{"fr":"Les pensions de Karadut préparent des dîners maison pour les clients partant au lever du soleil ; de retour à Adıyaman, goûtez le çiğ köfte et les desserts gorgés de pistache."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/nemrut-1.jpg","cap":{"fr":"Le lever du soleil sur la terrasse est"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/nemrut-2.jpg","cap":{"fr":"Les têtes des dieux aux pieds de leur roi"}}]},"mardin":{"long":{"fr":["Mardin dévale un versant en gradins de calcaire couleur de miel, chaque toit formant une terrasse ouverte sur la plaine mésopotamienne, vers la Syrie — au crépuscule, la vue se dissout simplement dans une brume dorée. Arabes, Kurdes, Turcs, chrétiens syriaques et, autrefois, une importante communauté juive ont bâti cette ville ensemble, et cela se voit : minarets et clochers se partagent la ligne d’horizon, et l’on entend cinq langues dans les ruelles du bazar, larges comme un âne.","La gloire de Mardin est sa pierre sculptée — levez les yeux vers les portails, les médersas Zinciriye et Kasımiye, le minaret cannelé de la Grande Mosquée. Juste à l’extérieur, le monastère de Deyrulzafaran, couleur safran, célèbre l’office en araméen, la langue de Jésus, depuis le Ve siècle ; plus loin sur le plateau du Tur Abdin, Mor Gabriel est l’un des plus anciens monastères encore en activité au monde. Achetez de l’argent en filigrane (telkari), goûtez l’amer café mırra et dormez dans une demeure de pierre avec la plaine sous votre fenêtre."]},"getting":{"fr":"L’aéroport de Mardin (MQM) est à 20 min de la vieille ville ; des bus relient Şanlıurfa (3 h) et Diyarbakır (1 h 30) pour un circuit du sud-est."},"eat":{"fr":"Kaburga dolması (côtes d’agneau farcies au riz), kebab aux cerises, confiseries aux amandes et l’amer café mırra versé d’un pot en laiton."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/mardin-1.jpg","cap":{"fr":"Demeures de pierre en terrasses au-dessus de la plaine"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/mardin-2.jpg","cap":{"fr":"Façades sculptées de la vieille ville"}}]}};
var UZUNGOL = {"id":"uzungol","img":"https://api.bubixo.com/discover-turkiye/assets/uzungol.jpg","region":"north","unesco":false,"name":{"fr":"Uzungöl"},"desc":{"fr":"Un lac de montagne immobile à 1 090 m, avec une mosquée au minaret élancé au bord de l’eau et une forêt d’épicéas qui monte dans la brume — la carte postale de la mer Noire et une échappée fraîche même en plein été."},"loc":{"fr":"Çaykara, Trabzon"},"best":{"fr":"Mai–oct. ; les matins de brume sont magiques"},"tip":{"fr":"Passez la nuit — le lac est le plus calme avant l’arrivée des bus de la journée et après leur départ."}};
